        code: 'cc_compose exec -T server /usr/local/bin/consolecrypt-server admin limits show --email user@example.com\ncc_compose exec -T server /usr/local/bin/consolecrypt-server admin limits set \\\n  --email user@example.com push_account_rate=600/min max_vault_objects=200000\ncc_compose exec -T server /usr/local/bin/consolecrypt-server admin limits reset --email user@example.com',
