        code: 'config:\n  requireRequestProof: true\n  objectSharingEnabled: true\n  sharedNotesEnabled: true\n  rateLimit:\n    mode: enforce\n    limits:\n      push_account: {rate: "600/min", burst: 600}\n  quotas:\n    maxVaultObjects: 200000\nextraEnv:\n  - name: CC_MAX_TEAM_MEMBERS\n    value: "50"',
